<script lang="ts">
let selected=0;
let direction=1;
function select(index:number){direction=index>selected?1:-1;selected=index;}
const stages=[{name:'Keyframes 2D',mark:'01',detail:'Poses, intervalos e transformação. O movimento começa no desenho de cada cena.',label:'Quadros & movimento'},{name:'Ritmo musical',mark:'02',detail:'O corte acompanha a música. Entradas, pausas e mudanças de intensidade dão forma ao trecho.',label:'Som & tempo'},{name:'Direção visual',mark:'03',detail:'Cor, composição e linguagem gráfica em diálogo com o artista. A participação está creditada em cada projeto.',label:'Intenção & imagem'}];
</script>
<div class="process-panel" data-environment-pop>
 <div class="process-panel-top"><span>NA EDIÇÃO</span><span aria-hidden="true">● 24 / FRAME</span></div>
 <p class="process-panel-label">Explore o processo</p>
 <div class="process-options" style={`--selected:${selected}`} role="group" aria-label="Etapas do processo"><span class="process-indicator" aria-hidden="true"></span>{#each stages as stage,i}<button aria-pressed={selected===i} onclick={()=>select(i)}><span>{stage.mark}</span>{stage.name}<span aria-hidden="true">↗</span></button>{/each}</div>
 <div class="process-detail" aria-live="polite" style={`--direction:${direction}`}>{#key selected}<div class="process-content"><span>{stages[selected].label}</span><p>{stages[selected].detail}</p><div class="frame-bars" aria-hidden="true">{#each Array(12) as _,i}<i class:lit={i<4*(selected+1)}></i>{/each}</div></div>{/key}</div>
 <span class="process-sticker" aria-hidden="true">作画</span>
</div>
<style>
.process-panel{position:relative;margin-top:35px;max-width:640px;border:2px solid #111315;background:#111315;color:#f8f3e8;box-shadow:10px 10px 0 #c8ff00;transform:rotate(1.5deg);padding:22px}.process-panel-top{display:flex;justify-content:space-between;gap:15px;font:500 13px var(--mono);border-bottom:1px solid #f8f3e84a;padding-bottom:15px}.process-panel-top>span:last-child{color:#c8ff00}.process-panel-label{font:700 24px var(--display);margin:20px 0}.process-options{display:flex;flex-direction:column;gap:8px}.process-options button{display:flex;align-items:center;gap:14px;min-height:46px;padding:12px;background:transparent;border:1px solid #f8f3e84a;color:#f8f3e8;text-align:left;font:600 16px var(--font)}.process-options button>span:first-child{font:500 13px var(--mono)}.process-options button>span:last-child{margin-left:auto}.process-options button[aria-pressed=true]{background:#c8ff00;color:#111315;transform:translateX(-5px);box-shadow:5px 4px 0 #fa7155}.process-options button:focus-visible{outline:3px solid #fa7155;outline-offset:3px}.process-detail{margin-top:22px;min-height:132px}.process-content>span{font:500 13px var(--mono);color:#c8ff00}.process-content>p{font:400 16px/1.6 var(--font);margin-top:12px}.frame-bars{display:flex;gap:5px;margin-top:20px}.frame-bars>i{display:block;width:8%;height:7px;background:#f8f3e830}.frame-bars>i.lit{background:#fa7155}.process-sticker{position:absolute;right:-18px;top:-25px;background:#fa7155;color:#111315;font:400 24px var(--jp);padding:7px 15px;transform:rotate(8deg);border:2px solid #111315}
.process-options{position:relative;isolation:isolate;gap:8px}.process-options button{height:52px;position:relative;transition:color .2s;background:transparent!important;transform:none!important;box-shadow:none!important}.process-indicator{position:absolute;left:-5px;top:0;right:0;height:52px;background:#b8ff01;box-shadow:5px 4px 0 #fa7155;transform:translateY(calc(var(--selected)*60px));transition:transform .22s cubic-bezier(.2,.7,.3,1);z-index:-1}.process-content{animation:process-enter .22s ease-out}.process-detail{min-height:160px}@keyframes process-enter{from{opacity:.4;transform:translateY(calc(var(--direction)*8px))}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){.process-indicator{transition:none}.process-content{animation:none}}
</style>
